/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

s32 playDistanceSound(s32, f32, M2C_UNK);               /* extern */
M2C_UNK updateSfxPanFromMarker(s32, s32, s32, M2C_UNK);      /* extern */
f32 findNearestTrackMarker(s32, u16 *);                      /* extern */
extern u32 gTrackMarkerParents[];
extern s32 gBonusObjects;

/* Plays a sound attenuated by distance from the emitter and pans it toward the nearest track marker (skipped for the bonus object); returns the voice. */ s32 playSoundAtPos(u16 soundId, void * emitter) {
    u16 markerIndex;
    s32 voice;
    s32 id;

    id = soundId & 0xFFFF;
    if (id == 0) {
        return 0;
    }
    voice = playDistanceSound(id, findNearestTrackMarker(emitter, &markerIndex), 0xFF);
    if (emitter != (gBonusObjects + 0x24)) {
        updateSfxPanFromMarker(voice, gTrackMarkerParents[markerIndex], emitter, 0);
    }
    return voice;
}
